// Este código unifica los datos entrantes sin importar si vienen de WhatsApp o Gmail
const items = $input.all();
const results = [];

for (const item of items) {
  let canal = 'desconocido';
  let remitente = '';
  let textoMensaje = '';

  // Identificar si viene de Evolution API (WhatsApp) o de Gmail
  if (item.json.body && item.json.body.data) {
    canal = 'whatsapp';
    remitente = item.json.body.data.key.remoteJid || '';
    textoMensaje = item.json.body.data.message?.conversation || item.json.body.data.message?.extendedTextMessage?.text || '';
  } else if (item.json.text || item.json.subject) {
    canal = 'gmail';
    remitente = item.json.from || '';
    textoMensaje = item.json.text || item.json.snippet || '';
  }

  results.push({
    json: {
      canal: canal,
      remitente: remitente,
      texto: textoMensaje,
      procesadoEn: new Date().toISOString()
    },
    // Mantiene los archivos adjuntos binarios si existen
    binary: item.binary
  });
}

return results;

